ucs.falcon_logscale_query:
(#event_simpleName=ProcessRollup2 OR #event_simpleName=UserLogon)
| case {
    #event_simpleName=ProcessRollup2 ImageFileName=/\\(procdump|procdump64|sqldumper)\.exe$/i CommandLine=/(lsass|-ma |-mm )/i | stage:="lsass_dump";
    #event_simpleName=ProcessRollup2 ImageFileName=/\\rundll32\.exe$/i CommandLine=/comsvcs\.dll.*MiniDump/i | stage:="lsass_dump";
    #event_simpleName=ProcessRollup2 ImageFileName=/\\(powershell|pwsh)\.exe$/i CommandLine=/(MiniDumpWriteDump|Out-Minidump|Invoke-Mimikatz|sekurlsa::|lsadump::)/i | stage:="lsass_dump";
    #event_simpleName=ProcessRollup2 ImageFileName=/\\(psexec|psexesvc|paexec)\.exe$/i | stage:="svc_exec";
    #event_simpleName=ProcessRollup2 ParentBaseFileName=/^services\.exe$/i ImageFileName=/\\(Windows\\\\Temp|PerfLogs|ProgramData|ADMIN\$|C\$)\\\\[^\\\\]+\.exe$/i | stage:="svc_exec";
    #event_simpleName=UserLogon LogonType=3 | stage:="smb_logon";
    * | stage:="other";
}
| stage!="other"
| groupBy([aid, ComputerName, UserName], function=[count(field=stage, distinct=true, as=stages), collect([stage, ImageFileName, CommandLine, RemoteAddressIP4])])
| stages >= 2
